/** Raw inline SVG source for a chassis. Useful for map tokens and tooltips. */
export function unitSilhouette(type: UnitType): string {
  return SILHOUETTE[type];
}

const TRAIT_LABEL: Record<Trait, string> = {
  cover_bonus: '+1 DEF IN COVER',
  no_rough_end: 'NO REST ON ROUGH',
  ignores_obstacles: 'IGNORES OBSTACLES',
  map_only: 'MAP ONLY',
};

/** Accent colour per chassis so a mixed roster is scannable. */
const ACCENT: Record<UnitType, string> = {
  exo: 'var(--cyan)',
  walker: 'var(--teal)',
  pallet: 'var(--amber)',
  flyer: 'var(--violet)',
  heavy_pallet: 'var(--gold)',
  elite_flyer: 'var(--magenta)',
  drone: 'var(--lime)',
};

/** Accent token for a chassis — shared with the render layer's token colours. */
export function unitAccent(type: UnitType): string {
  return ACCENT[type];
}

function costRow(type: UnitType): HTMLElement {
  const { cost } = UNITS[type];
  const row = el('span', { class: 'uchip__cost' }, el('span', { class: 'm', text: `${fmtNum(cost.m)}M` }));
  if (cost.g > 0) row.appendChild(el('span', { class: 'g', text: `${fmtNum(cost.g)}G` }));
  return row;
}

function statSpan(key: string, value: number): HTMLElement {
  return el('span', { class: 'uchip__stat' }, `${key} `, el('b', { text: String(value) }));
}

// ─────────────────────────────────────────────────────────────────────────────
// Chip
// ─────────────────────────────────────────────────────────────────────────────

export interface UnitChipOpts {
  /** Stack size — renders `×N` on the right. */
  count?: number;
  /** Current HP — renders a small HP meter when `maxHp` is also given. */
  hp?: number;
  maxHp?: number;
  selected?: boolean;
  onClick?: () => void;
  /** 40px compact row for dense lists. */
  small?: boolean;
  /** Dim + desaturate (destroyed units). */
  dead?: boolean;
  class?: string;
}

/**
 * One chassis row: silhouette, designation, live stats, cost and stack size.
 */
export function unitChip(type: UnitType, opts: UnitChipOpts = {}): HTMLElement {
  const def = UNITS[type];
  const classes = ['uchip'];
  if (opts.small) classes.push('uchip--small');
  if (opts.selected) classes.push('uchip--sel');
  if (opts.dead) classes.push('uchip--dead');
  if (opts.onClick) classes.push('uchip--btn');
  if (opts.class) classes.push(opts.class);

  const root: HTMLElement = opts.onClick
    ? el('button', {
        class: classes.join(' '),
        style: `--accent:${ACCENT[type]}`,
        attrs: { type: 'button' },
        aria: { label: def.name, pressed: opts.selected === true },
      })
    : el('div', {
        class: classes.join(' '),
        style: `--accent:${ACCENT[type]}`,
      });

  const art = el('div', { class: 'uchip__art' });
  art.appendChild(svgEl(SILHOUETTE[type]));
  root.appendChild(art);

  const main = el('div', { class: 'uchip__main' });
  main.appendChild(el('div', { class: 'uchip__name', text: def.name }));
  main.appendChild(el('div', { class: 'uchip__code', text: def.codename }));

  const stats = el('div', { class: 'uchip__stats' });
  if (def.combat) {
    stats.appendChild(statSpan('HP', def.hp));
    stats.appendChild(statSpan('ATK', def.atk));
    stats.appendChild(statSpan('RNG', def.rng));
    stats.appendChild(statSpan('MOV', def.mov));
  } else {
    stats.appendChild(el('span', { class: 'uchip__stat', text: 'RECON — NON-COMBAT' }));
  }
  stats.appendChild(costRow(type));
  main.appendChild(stats);
  root.appendChild(main);

  const right = el('div', { class: 'uchip__right' });
  if (opts.count !== undefined) {
    right.appendChild(el('div', { class: 'uchip__count', text: String(opts.count) }));
  }
  if (opts.hp !== undefined && opts.maxHp !== undefined && opts.maxHp > 0) {
    const hpMeter = meter(opts.hp, opts.maxHp, { height: 5, autoTint: true });
    hpMeter.el.classList.add('uchip__hp');
    right.appendChild(hpMeter.el);
  }
  if (right.childElementCount > 0) root.appendChild(right);

  if (opts.onClick) {
    const handler = opts.onClick;
    root.addEventListener('click', () => handler());
  }

  return root;
}

// ─────────────────────────────────────────────────────────────────────────────
// Stat block
// ─────────────────────────────────────────────────────────────────────────────

function statCell(k: string, v: string): HTMLElement {
  return el(
    'div',
    { class: 'ustat__cell' },
    el('span', { class: 'ustat__k', text: k }),
    el('span', { class: 'ustat__v', text: v }),
  );
}

/** Full dossier for a chassis: art, stats grid, traits, cost, build time, lore. */
export function unitStatBlock(type: UnitType): HTMLElement {
  const def = UNITS[type];

  const art = el('div', { class: 'ustat__art', style: `--accent:${ACCENT[type]}` });
  const artSvg = svgEl(SILHOUETTE[type]);
  artSvg.setAttribute('style', `stroke:${ACCENT[type]}`);
  art.appendChild(artSvg);

  const head = el(
    'div',
    { class: 'ustat__head' },
    art,
    el(
      'div',
      { class: 'grow' },
      el('div', { class: 'ustat__name', text: def.name }),
      el('div', { class: 'ustat__code', text: def.codename }),
      costRow(type),
    ),
  );

  const grid = el(
    'div',
    { class: 'ustat__grid' },
    statCell('HP', String(def.hp)),
    statCell('ATK', String(def.atk)),
    statCell('RNG', String(def.rng)),
    statCell('MOV', String(def.mov)),
  );

  const traits = el('div', { class: 'ustat__traits' });
  traits.appendChild(
    el('span', { class: 'trait', text: `BUILD ${fmtDuration(def.buildTimeMs)}` }),
  );
  if (!def.combat) traits.appendChild(el('span', { class: 'trait', text: 'NON-COMBAT' }));
  for (const trait of def.traits) {
    traits.appendChild(el('span', { class: 'trait', text: TRAIT_LABEL[trait] }));
  }

  return el(
    'div',
    { class: 'ustat', style: `--accent:${ACCENT[type]}` },
    head,
    grid,
    traits,
    el('p', { class: 'ustat__blurb selectable', text: def.blurb }),
  );
}
